import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { getAppointments } from '../services/api';

const TimeSlotPicker = ({ doctorId, date, availableSlots, setAvailableSlots }) => {
  const [bookedSlots, setBookedSlots] = useState([]);

  const timeSlots = [
    '09:00', '10:00', '11:00', '14:00', '15:00', '16:00'
  ];

  useEffect(() => {
    if (doctorId && date) {
      fetchBookedSlots();
    }
  }, [doctorId, date]);

  const fetchBookedSlots = async () => {
    try {
      const response = await getAppointments();
      const booked = response.data
        .filter(apt =>
          apt.doctorId === doctorId &&
          new Date(apt.date).toDateString() === date.toDateString() &&
          ['booked', 'rescheduled'].includes(apt.status)
        )
        .map(apt => apt.timeSlot);
      setBookedSlots(booked);
    } catch (error) {
      console.error('Error fetching booked slots:', error);
    }
  };

  const isSlotAvailable = (slot) => {
    const count = bookedSlots.filter(s => s === slot).length;
    return count < 10; // Max 10 patients per slot
  };

  return (
    <div>
      <h2 className="text-2xl font-semibold text-gray-800 dark:text-white mb-4">Available Time Slots</h2>
      <div className="grid grid-cols-2 gap-3">
        {timeSlots.map((slot) => {
          const available = isSlotAvailable(slot);
          const remaining = 10 - bookedSlots.filter(s => s === slot).length;

          return (
            <motion.button
              key={slot}
              className={`p-4 rounded-lg font-medium transition-all duration-300 ${
                available
                  ? 'bg-green-100 dark:bg-green-800 text-green-800 dark:text-green-200 hover:bg-green-200 dark:hover:bg-green-700 border-2 border-green-300 dark:border-green-600'
                  : 'bg-gray-200 dark:bg-gray-700 text-gray-500 dark:text-gray-400 cursor-not-allowed border-2 border-gray-300 dark:border-gray-600'
              }`}
              disabled={!available}
              whileHover={available ? { scale: 1.05 } : {}}
              whileTap={available ? { scale: 0.95 } : {}}
            >
              <div className="text-center">
                <div className="text-lg">{slot}</div>
                <div className="text-sm mt-1">
                  {available ? `${remaining} slots left` : 'Full'}
                </div>
              </div>
            </motion.button>
          );
        })}
      </div>
      <div className="mt-4 text-sm text-gray-600 dark:text-gray-400">
        <p>🟢 Available • 🔴 Full</p>
        <p>Maximum 10 patients per time slot</p>
      </div>
    </div>
  );
};

export default TimeSlotPicker;
